<?php
declare(strict_types=1);
require_once __DIR__.'/config.inc.php';require_once __DIR__.'/sqlite_schema.php';
function is_db_connected(PDO &$pdo):bool{try{$pdo->query('SELECT 1');return true;}catch(Throwable $e){error_log('[DB] SQLite check failed: '.$e->getMessage());return false;}}
function pg_pool(bool $force_reconnect=false):PDO{static $instance=null;if(!$force_reconnect&&$instance instanceof PDO&&is_db_connected($instance))return$instance;$path=DB_PATH;$dir=dirname($path);if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('No se pudo crear directorio SQLite: '.$dir);try{$instance=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$instance->exec('PRAGMA foreign_keys=ON');$instance->exec('PRAGMA busy_timeout=5000');$instance->exec('PRAGMA journal_mode=WAL');if(method_exists($instance,'sqliteCreateFunction')){$instance->sqliteCreateFunction('now',static fn():string=>date('Y-m-d H:i:s'),0);$instance->sqliteCreateFunction('CONCAT',static function(...$args):string{return implode('',array_map(static fn($v)=>(string)($v??''),$args));},-1);$instance->sqliteCreateFunction('RIGHT',static function($value,$length):string{$value=(string)$value;$length=max(0,(int)$length);return$length===0?'':substr($value,-$length);},2);}initializeNebulaPOSSchema($instance);return$instance;}catch(PDOException $e){$instance=null;throw new RuntimeException('Database connection failed: '.$e->getMessage(),0,$e);}}
final class PgConnection{public static function get():PDO{return pg_pool();}}
$db=pg_pool();
